import React, { useEffect, useRef, useState } from "react";
import styled from "styled-components";
import fetchStructDataWithFilters from "."

const Container = styled.div`
  height: 88vh;
  display: flex;
  flex-direction: column;
  background: #f4f4f9;
  font-family: Arial, sans-serif;
  width: 162vh;
`;

const ContentWrapper = styled.div`
  display: flex;
  flex: 1;
  width: 100%;
`;

const MapContainer = styled.div`
  flex: 1;
  min-width: 300px;
  border-bottom: 2px solid #ddd;
`;

const MarkerList = styled.div`
  padding: 20px;
  background: #fff;
  overflow-y: auto;
  max-height: 100%;
  max-width: 800px;
  width: 100%;
  border-left: 2px solid #ddd;
  box-shadow: 2px 0 8px rgba(0, 0, 0, 0.1);
`;

const Table = styled.table`
  width: 100%;
  border-collapse: collapse;
  margin-top: 15px;
`;

const TableHeader = styled.th`
  padding: 12px;
  background-color: #4CAF50;
  color: white;
  font-weight: bold;
  text-align: left;
  border-bottom: 2px solid #ddd;
`;

const TableRow = styled.tr`
  border-bottom: 1px solid #ddd;
  &:hover {
    background-color: #f8f8f8;
  }
`;

const TableCell = styled.td`
  padding: 12px;
  text-align: left;
  color: #333;
`;

const StatusBadge = styled.span`
  padding: 6px 12px;
  border-radius: 20px;
  font-weight: bold;
  color: white;
  background: ${(props) =>
    props.status === "sent"
      ? "#4CAF50"
      : props.status === "processing"
      ? "#FFB900"
      : "#FF6347"};
  font-size: 12px;
  text-transform: capitalize;
`;

const DGisMap = () => {
  const mapContainer = useRef(null);
  const mapRef = useRef(null);
  const [markers, setMarkers] = useState([
    { lat: 55.35, lng: 86.07, label: "Кемерово", status: "not_sent" },
    { lat: 55.34, lng: 86.12, label: "СКЭК", status: "sent" },
  ]);

  useEffect(() => {
    if (!mapContainer.current || mapRef.current) return;

    const script = document.createElement("script");
    script.src = "https://maps.api.2gis.ru/2.0/loader.js?pkg=full";
    script.async = true;

    script.onload = () => {
      if (window.DG) {
        window.DG.then(() => {
          initMap();
        });
      }
    };

    document.body.appendChild(script);
    return () => document.body.removeChild(script);
  }, []);

  const initMap = () => {
    const map = window.DG.map(mapContainer.current, {
      center: [55.35, 86.07],
      zoom: 9,
      scrollWheelZoom: true,
    });

    map.setMaxBounds([
      [53.5, 84.0],
      [56.5, 89.0],
    ]);
    map.on("click", handleMapClick);

    markers.forEach((marker) => addMarker(map, marker));
    mapRef.current = map;
  };

  const handleMapClick = (e) => {
    const { lat, lng } = e.latlng;
    const label = prompt("Введите название метки:");

    if (label) {
      const status = prompt("Введите статус метки (not_sent, processing, sent):", "not_sent");
      if (["not_sent", "processing", "sent"].includes(status)) {
        const newMarker = { lat, lng, label, status };
        setMarkers((prev) => [...prev, newMarker]);
        addMarker(mapRef.current, newMarker);
      } else {
        alert("Некорректный статус!");
      }
    }
  };

  const addMarker = (map, { lat, lng, label, status }) => {
    const statusColors = {
      not_sent: "#ff6347",
      processing: "#FFB900",
      sent: "#4CAF50",
    };

    const icon = window.DG.divIcon({
      className: "custom-icon",
      html: `<div style="background:${statusColors[status]}; color:#000; border-radius:50%;
                     width:40px; height:40px; display:flex; align-items:center;
                     justify-content:center; font-size:12px; font-weight:bold;">${label}</div>`,
      iconSize: [40, 40],
      iconAnchor: [20, 20],
    });

    const marker = window.DG.marker([lat, lng], { icon })
      .addTo(map)
      .bindPopup(`${label} (${lat.toFixed(4)}, ${lng.toFixed(4)}) - ${getStatusText(status)}`);

    return marker;
  };

  const getStatusText = (status) => ({
    sent: "Отчет отправлен",
    processing: "В обработке",
    not_sent: "Не отправлен",
  }[status]);

  const handleMarkerClick = (lat, lng) => {
    if (mapRef.current) {
      mapRef.current.setView([lat, lng], 12, { animate: true });
    }
  };

  return (
    <Container>
      <ContentWrapper>
        <MapContainer ref={mapContainer} />
        <MarkerList>
          <h3 style={{ textAlign: "center" }}>Список меток организаций</h3>
          <Table>
            <thead>
              <tr>
                <TableHeader>Название</TableHeader>
                <TableHeader>Координаты</TableHeader>
                <TableHeader>Статус</TableHeader>
              </tr>
            </thead>
            <tbody>
              {markers.map((marker, index) => (
                <TableRow key={index} onClick={() => handleMarkerClick(marker.lat, marker.lng)}>
                  <TableCell>{marker.label}</TableCell>
                  <TableCell>{`${marker.lat.toFixed(4)}, ${marker.lng.toFixed(4)}`}</TableCell>
                  <TableCell>
                    <StatusBadge status={marker.status}>{getStatusText(marker.status)}</StatusBadge>
                  </TableCell>
                </TableRow>
              ))}
            </tbody>
          </Table>
        </MarkerList>
      </ContentWrapper>
    </Container>
  );
};

export default DGisMap;
